from fastapi import FastAPI, Depends, Query

app = FastAPI()

# Dependency function
def common_parameters(q: str | None = Query(None, description="Search query")):
    return {"q": q}

# Path operation that uses the dependency
@app.get("/items/")
async def read_items(params: dict = Depends(common_parameters)):
    return params

